def button(label,href,kind='',arrow=True):
    return f'<a class="button {kind}" href="{href}">{label}{icon("arrow") if arrow else ""}</a>'
# Hình SVG gradient: lối dạo, hồ nước, tán cây và cửa vòm lấy cảm hứng từ vườn Huế.
def scene(seed=1,kind='garden'):
    rng=random.Random(seed)
    sky=['#d9e1ba','#c7d6b0','#b8d5c4','#e1d4a9','#cadfbc'][seed%5]
    shapes=[]
    for i in range(42):
        x=rng.randrange(-30,850); y=rng.randrange(80,430);r=rng.randrange(25,95)
        fill=rng.choice(['#284e36','#365b3d','#496a43','#698455','#77915c'])
        shapes.append(f'<circle cx="{x}" cy="{y}" r="{r}" fill="{fill}" opacity=".8"/>')
    foliage=''.join(shapes)
    detail=[]
    for i in range(160):
        x=rng.randrange(0,800); y=rng.choice([rng.randrange(400,580),rng.randrange(640,1000)])
        if 250<x<570 and y>500:continue
        fill=rng.choice(['#497746','#658e50','#90a664','#b0bb7a','#2d5b3b','#7c9c56'])
        detail.append(f'<path d="M{x} {y+40}q-18-45-30-58 35 0 30 58q0-48 28-65 9 41-28 65" fill="{fill}"/>')
    if kind=='water':
        center='<ellipse cx="395" cy="665" rx="265" ry="105" fill="url(#water)"/><ellipse cx="395" cy="663" rx="230" ry="77" fill="none" stroke="#c4d5a1" opacity=".35"/><path d="M370 660q30-22 47 3-30 25-47-3m100 32q22-20 40 0-23 20-40 0" fill="#e8b688"/>'
    elif kind=='office':
        center='<rect x="145" y="230" width="520" height="375" fill="#d8d6b4"/><path d="M170 260h470v290H170z" fill="#64887b"/><path d="M325 260v290m160-290v290M170 400h470" stroke="#e7e3c9" stroke-width="12"/><path d="M220 580h360l70 110H150z" fill="#b1b899"/>'
    else:
        center='<path d="M244 540V336a156 156 0 0 1 312 0v204" fill="#d4c99f"/><path d="M280 540V338a120 120 0 0 1 240 0v202" fill="#536f50"/><path d="M297 540V345a103 103 0 0 1 206 0v195" fill="#789467"/><path d="M315 540V354a85 85 0 0 1 170 0v186" fill="#a4b185"/><path d="M342 540V359a58 58 0 0 1 116 0v181" fill="#ced0a6"/><path d="M400 425v120m-40-62 40-40 35 35" stroke="#81946b" fill="none" stroke-width="4"/>'
    s=f'''<svg xmlns="http://www.w3.org/2000/svg" width="800" height="1000" viewBox="0 0 800 1000"><defs><linearGradient id="sky" x2="0" y2="1"><stop stop-color="{sky}"/><stop offset="1" stop-color="#789b70"/></linearGradient><linearGradient id="floor" x2="0" y2="1"><stop stop-color="#66825a"/><stop offset="1" stop-color="#20432e"/></linearGradient><linearGradient id="water" x2="1" y2="1"><stop stop-color="#8ab6a2"/><stop offset="1" stop-color="#235c59"/></linearGradient><radialGradient id="light"><stop stop-color="#f9efbf" stop-opacity=".65"/><stop offset="1" stop-color="#e9e9b1" stop-opacity="0"/></radialGradient><filter id="grain"><feTurbulence baseFrequency=".55" numOctaves="3" stitchTiles="stitch"/><feColorMatrix type="saturate" values="0"/><feComponentTransfer><feFuncA type="linear" slope=".07"/></feComponentTransfer><feBlend in="SourceGraphic" mode="multiply"/></filter></defs><g filter="url(#grain)"><path fill="url(#sky)" d="M0 0h800v1000H0z"/><circle cx="530" cy="180" r="100" fill="#e8e4b6" opacity=".7"/>{foliage}<path d="M0 470q180-55 390 0t410-20v550H0Z" fill="url(#floor)"/>{center}<path d="M352 540h100l55 75H305zM300 630h210l36 70H264zM248 720h310l50 92H193zM170 840h455l83 150H80z" fill="#c3c4a6"/><path d="M352 542h100M300 632h210M248 723h310M170 843h455" stroke="#e2dec0" stroke-width="5"/><ellipse cx="120" cy="650" rx="140" ry="65" fill="#335639"/><ellipse cx="730" cy="580" rx="190" ry="82" fill="#365e3e"/>{''.join(detail)}<path d="M33 0q35 260 50 470M55 205Q180 125 200 0M65 310Q-20 230 0 140M738 0q-70 220-50 400" stroke="#38543b" stroke-width="18" fill="none"/><path d="M0 0h800v1000H0z" fill="url(#light)"/></g></svg>'''
    return 'data:image/svg+xml,'+quote(s)
def img(seed,alt,kind='garden',cls=''):
    return f'<img class="{cls}" src="{scene(seed,kind)}" data-src="" data-image-path="images/anh-vuon-{seed}.webp" alt="{alt}" loading="lazy" decoding="async" width="800" height="1000">'
