def writepage(filename,title,desc,body,active=None,extra=None):
    url=DOMAIN+('/' if filename=='index.html' else '/'+filename)
    items=[{'@type':'ListItem','position':1,'name':'Trang chủ','item':DOMAIN+'/'}]
    if filename!='index.html':
        if filename.startswith('du-an-'):items.append({'@type':'ListItem','position':2,'name':'Dự án','item':DOMAIN+'/du-an.html'})
        items.append({'@type':'ListItem','position':len(items)+1,'name':title.split(' – ')[0],'item':url})
    schema=[{'@context':'https://schema.org','@type':'BreadcrumbList','itemListElement':items}]
    if extra:schema.append(extra)
    content=f'''<!doctype html><html lang="vi"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover"><title>{html.escape(title)}</title><meta name="description" content="{html.escape(desc,quote=True)}"><meta name="keywords" content="thiết kế cảnh quan Huế, làm vườn Huế, chăm sóc cây cảnh, hồ cá Koi Huế, tiểu cảnh bonsai, sân vườn Huế"><meta name="theme-color" content="#1B4332"><meta property="og:title" content="{html.escape(title,quote=True)}"><meta property="og:description" content="{html.escape(desc,quote=True)}"><meta property="og:type" content="website"><meta property="og:url" content="{url}"><meta property="og:locale" content="vi_VN"><meta property="og:site_name" content="{BRAND}"><link rel="canonical" href="{url}"><link rel="icon" href="data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 32 32'%3E%3Crect width='32' height='32' rx='8' fill='%231B4332'/%3E%3Cpath d='M8 24Q3 7 25 6Q27 27 8 24L21 11' fill='none' stroke='%2374C69D' stroke-width='2'/%3E%3C/svg%3E"><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><style>{re.sub(r'/\*.*?\*/','',CSS,flags=re.S).replace(chr(10),'')}</style><script type="application/ld+json">{json.dumps(schema,ensure_ascii=False)}</script></head><body>{header(active or filename)}<main id="noi-dung">{body}</main>{footer()}<script>{JS}</script></body></html>'''
    (OUT/filename).write_text(content)
    PAGES.append(filename)
