for p in PROJECTS:
    detail=f'<section class="page-hero project-hero"><div class="container">{breadcrumb(p["name"],True)}<div class="eyebrow">{p["type"]}</div><h1>{p["name"]}</h1><p>{p["place"]} · Một khoảng xanh, một câu chuyện riêng.</p><div class="project-hero__image">{img(p["seed"],"Minh họa tổng thể "+p["name"],p["kind"])}</div></div></section><div class="info-bar"><div class="container info-bar__inner">'+''.join(f'<div><small>{a}</small><strong>{b}</strong></div>' for a,b in [('Loại dịch vụ',p['type']),('Diện tích',p['size']),('Năm hoàn thành',p['year']),('Thời gian',p['days'])])+'</div></div>'
    detail+=f'<section class="section"><div class="container detail-grid"><article class="prose"><h2>Giới thiệu dự án</h2><p>{p["intro"]}</p><h2>Thử thách & Giải pháp</h2><p>{p["challenge"]}</p><p>{p["solution"]}</p><p>Trước khi bàn giao, từng khu vực được kiểm tra cùng khách hàng. Các hướng dẫn vận hành và chăm sóc được trình bày rõ để công trình tiếp tục phát triển ổn định sau khi hoàn thành.</p><h2>Kết quả đạt được</h2><ul><li>Không gian xanh hài hòa với kiến trúc và nhu cầu sử dụng.</li><li>Bố cục lối đi, điểm nghỉ và cây trồng được tổ chức rõ ràng.</li><li>Vật liệu phù hợp với điều kiện thời tiết tại địa phương.</li><li>Hệ thống kỹ thuật có vị trí tiếp cận thuận tiện để bảo trì.</li><li>Khách hàng được hướng dẫn chăm sóc và hỗ trợ sau bàn giao.</li></ul><p class="demo-note">Hồ sơ dự án mẫu; hình ảnh và thông số dùng để minh họa.</p></article><aside class="sidebar"><div class="sidebar__card"><h3>Thông tin dự án</h3><dl>'+''.join(f'<dt>{a}</dt><dd>{b}</dd>' for a,b in [('Loại dịch vụ',p['type']),('Địa điểm',p['place']),('Quy mô',p['size']),('Khách hàng',p['client']),('Năm',p['year'])])+f'</dl></div><div class="sidebar__card"><h3>Dịch vụ đã thực hiện</h3><ul><li>Khảo sát và lên ý tưởng</li><li>Thiết kế không gian và kỹ thuật</li><li>Lựa chọn cây, vật liệu</li><li>Thi công và hướng dẫn bảo dưỡng</li></ul><a class="text-link" href="dich-vu.html">Khám phá dịch vụ →</a></div><div class="sidebar__card"><h3>Bạn thích không gian này?</h3><p class="muted">Cùng tạo nên một khu vườn dành riêng cho bạn.</p>{button("Tư vấn dự án tương tự","lien-he.html")}</div></aside></div></section>'
    captions=['Tổng thể khu vườn','Lối dạo và thảm cây','Góc nhìn không gian xanh','Điểm nhấn cảnh quan','Chi tiết cây và vật liệu','Không gian nghỉ ngơi']
    detail+=f'<section class="section section--white"><div class="container">{heading("Một khu vườn, nhiều góc nhìn","Thư viện ảnh dự án","Chọn một hình để khám phá phối cảnh minh họa.")}<div class="gallery">'+''.join(f'<button class="gallery__item" aria-label="Xem ảnh {i+1}: {c}">{img(p["seed"]+i,"Minh họa "+c.lower()+" — "+p["name"],p["kind"])}<span>Phóng to ↗</span></button>' for i,c in enumerate(captions))+'</div></div></section><dialog class="lightbox" aria-label="Thư viện ảnh dự án"><button class="lightbox__close" aria-label="Đóng thư viện ảnh">'+icon('close')+'</button><div class="lightbox__body"><img class="lightbox__image" alt="Ảnh minh họa dự án đang xem" loading="lazy" decoding="async"><div class="lightbox__controls"><button data-prev aria-label="Ảnh trước">←</button><p class="lightbox__caption" aria-live="polite"></p><button data-next aria-label="Ảnh tiếp theo">→</button></div></div></dialog>'
    n,r,q=REVIEWS[p['quote']]
    detail+=f'<section class="section"><div class="container large-quote"><div class="eyebrow" style="justify-content:center">Lời chia sẻ từ khách hàng</div><blockquote>“{q}”</blockquote><p><strong>{n}</strong> · {r}</p><p class="demo-note">Đánh giá mẫu theo hồ sơ giới thiệu.</p></div></section><section class="section section--white"><div class="container">{heading("Tiếp tục khám phá","Những công trình khác")}<div class="project-grid project-grid--related">'+''.join(projectcard(x) for x in sorted([x for x in PROJECTS if x!=p],key=lambda x:-len(set(x['category'].split())&set(p['category'].split())))[:3])+'</div></div></section>'+cta()
