prices=[ [('Khảo sát thiết kế','Dưới 50 m²','Miễn phí'),('Thi công vườn','50–100 m²','Từ 15.000.000đ'),('Bảo trì hàng tháng','Hộ gia đình','Từ 500.000đ/lần')], [('Kiểm tra, tư vấn','Theo hiện trạng','Miễn phí'),('Chăm sóc định kỳ','Hộ gia đình','Từ 500.000đ/lần'),('Cắt tỉa cây lớn','Theo quy mô','Báo giá sau khảo sát')], [('Khảo sát hồ','Hộ gia đình','Miễn phí'),('Thiết kế và thi công','Theo thể tích','Báo giá sau khảo sát'),('Bảo trì hệ lọc','Theo thiết bị','Báo giá sau khảo sát')], [('Tư vấn bố cục','Theo không gian','Miễn phí'),('Tiểu cảnh, bonsai','Theo cây và đá','Báo giá theo phương án'),('Chăm sóc định kỳ','Hộ gia đình','Từ 500.000đ/lần')], [('Khảo sát hiện trạng','Dưới 50 m²','Miễn phí'),('Thi công vườn','50–100 m²','Từ 15.000.000đ'),('Chăm sóc định kỳ','Hộ gia đình','Từ 500.000đ/lần')], [('Khảo sát công trình','Theo khuôn viên','Miễn phí'),('Cung cấp, trồng cây','Theo chủng loại','Báo giá theo số lượng'),('Bảo dưỡng','Theo diện tích','Báo giá sau khảo sát')]]
servicebody=pagehero('Giải pháp xanh,<br>trọn vẹn từ tâm.','Từ một chậu cây nhỏ đến cả khuôn viên rộng lớn, chúng tôi đồng hành cùng bạn trong từng giai đoạn.','Dịch vụ của chúng tôi','Dịch vụ')+'<section class="section"><div class="container"><nav class="filters" aria-label="Danh mục dịch vụ">'+''.join(f'<a class="filter" href="#{s[0]}">{s[1]}</a>' for s in SERVICES)+'</nav>'
for i,s in enumerate(SERVICES):
    detailcopy=s[3]+' Mỗi phương án bắt đầu bằng việc lắng nghe mong muốn của khách hàng và quan sát điều kiện thực tế. Chúng tôi cân nhắc ánh sáng, gió, khả năng thoát nước và thói quen sử dụng để đề xuất giải pháp phù hợp. Vật liệu và cây trồng được lựa chọn theo ngân sách đã thống nhất, ưu tiên tính bền vững và sự thuận tiện khi chăm sóc. Trong quá trình thực hiện, đội ngũ cập nhật tiến độ và trao đổi rõ những điều chỉnh cần thiết. Khi bàn giao, bạn nhận được hướng dẫn vận hành cùng lịch chăm sóc đề xuất để không gian xanh tiếp tục phát triển theo thời gian.'
