about=pagehero('Gieo mầm xanh.<br>Vun trồng bình yên.','Một khu vườn không chỉ làm đẹp ngôi nhà. Đó còn là nơi chúng ta tìm lại sự cân bằng, kết nối và những niềm vui nhỏ mỗi ngày.','Câu chuyện Cố Đô','Về chúng tôi')+f'<section class="section"><div class="container detail-grid"><div class="prose"><div class="eyebrow">Từ tình yêu với đất và cây</div><h2>Mang tinh thần nhà vườn Huế<br>vào cuộc sống hôm nay.</h2><p>Sân Vườn Cố Đô ra đời từ tình yêu dành cho những khoảng xanh yên tĩnh của Huế: mái hiên có bóng cây, lối đi phủ rêu và tiếng nước nhẹ bên thềm nhà. Chúng tôi tin rằng dù diện tích lớn hay nhỏ, mỗi không gian đều có thể trở thành nơi con người thấy gần thiên nhiên hơn.</p><p>Với hơn 10 năm kinh nghiệm theo hồ sơ giới thiệu, đội ngũ Cố Đô đồng hành từ ý tưởng, thiết kế đến thi công và chăm sóc. Điều chúng tôi quan tâm không chỉ là khoảnh khắc bàn giao, mà còn là cách khu vườn phát triển và được sử dụng trong nhiều năm sau đó.</p><p>Lắng nghe kỹ, làm việc rõ ràng và chăm chút từng chi tiết là cách chúng tôi vun trồng niềm tin. Những giá trị ấy hiện diện trong từng bản vẽ, từng lựa chọn vật liệu và mỗi lần trở lại chăm sóc khu vườn của bạn.</p>{button("Gặp gỡ và trao đổi","lien-he.html")}</div><div>{img(28,"Minh họa khu vườn Huế yên bình với lối dạo xanh","garden","article-cover")}<p class="serif" style="font-size:26px;color:var(--clr-primary)">“Chúng tôi trồng cây,<br>để bạn trồng những kỷ niệm.”</p></div></div></section><section class="section section--white"><div class="container">{heading("Điều chúng tôi gìn giữ","Ba giá trị, một lời hứa.")}<div class="values">'+''.join(f'<article class="value" data-reveal>{icon(ico)}<h3>{title}</h3><p>{desc}</p></article>' for ico,title,desc in [('leaf','Thấu hiểu thiên nhiên','Chọn cây và vật liệu phù hợp với khí hậu, tận dụng ánh sáng và điều kiện thực tế của khu đất.'),('shield','Tận tâm với khách hàng','Lắng nghe mong muốn, minh bạch phương án và báo giá, giữ liên lạc xuyên suốt quá trình thực hiện.'),('garden','Bền vững qua thời gian','Thiết kế để dễ sử dụng, dễ chăm sóc và có thể thích nghi khi nhu cầu của gia đình thay đổi.')])+f'</div></div></section><section class="section"><div class="container">{heading("Những người cùng vun trồng","Đội ngũ đứng sau mỗi khu vườn","Phối hợp từ bản vẽ đầu tiên đến lần chăm sóc định kỳ.")}<div class="team">'+''.join(f'<article class="team__card"><div class="team__avatar">{img(31+i,"Minh họa công việc của "+title.lower())}</div><h3>{title}</h3><p>{desc}</p></article>' for i,(title,desc) in enumerate([('Nhóm thiết kế cảnh quan','Lắng nghe, khảo sát và chuyển mong muốn của bạn thành phương án không gian rõ ràng.'),('Đội thi công sân vườn','Tổ chức hiện trường, trồng cây và hoàn thiện từng hạng mục theo thiết kế đã thống nhất.'),('Nhóm chăm sóc & Bảo trì','Theo dõi sức khỏe cây, chăm sóc định kỳ và hỗ trợ khách hàng trong quá trình sử dụng.')]))+'</div></div></section>'+cta()
